```javascript
const orders = [
  { status: "paid", total: 20 },
  { status: "cancelled", total: 50 },
  { status: "paid", total: 15 },
];

const paidTotals = orders
  .filter((order) => order.status === "paid")
  .map((order) => order.total);
const revenue = paidTotals.reduce((sum, total) => sum + total, 0);
console.log(paidTotals, revenue); // [20, 15] 35
```

```javascript
const user = { id: 7, name: "Ada" };
const users = [user, { id: 8, name: "Lin" }];

console.log(Array.isArray(users)); // true
console.log(users.map((item) => item.name)); // ["Ada", "Lin"]

const byId = new Map(users.map((item) => [item.id, item]));
console.log(byId.get(8).name); // Lin
```

```javascript
const state = { user: { name: "Ada", address: { city: "London" } } };

const next = {
  ...state,
  user: {
    ...state.user,
    address: { ...state.user.address, city: "Paris" },
  },
};

console.log(state.user.address.city); // London
console.log(next.user.address.city);  // Paris
```
